-- Hướng tu quests become two steps each (the first step is new, the old quest is now the second step), and the contents differ per path.
-- Seeding never overwrites rows (INSERT OR IGNORE), so the stored definitions are written here; a test checks they match the seed.
-- A path quest that was active under the old single-step definition would skip step 1: drop those rows (finished ones stay).
DELETE FROM character_quests WHERE quest_id IN ('path_kiem', 'path_thuat', 'path_dan') AND state = 'active';
INSERT OR REPLACE INTO quests (id, chain, seq, enabled, def, updated_at) VALUES ('path_kiem_1', 'path', 1, 1, '{"id":"path_kiem_1","chain":"path","seq":1,"giver":"path_kiem","titleVi":"Thử kiếm","descVi":"Kiếm tu lấy chiến đấu làm gốc. Hãy ra Hắc Mộc Lâm hạ 30 con quái để chứng tỏ kiếm tâm, rồi quay lại báo cho ta.","enabled":true,"requires":null,"minRealm":1,"path":"kiem","objective":{"kind":"kill","count":30,"map":"forest"},"rewards":{"items":[{"item":"dai_hoi_huyet_dan","qty":2}]}}', 0);
UPDATE quests SET seq = 2, def = '{"id":"path_kiem","chain":"path","seq":2,"giver":"path_kiem","titleVi":"Kiếm Tâm","descVi":"Kiếm tâm phải được tôi trong nguy hiểm. Vào U Minh Động hạ 3 quái Tinh Anh hoặc Đại Yêu, ta sẽ trao Kiếm Tu Lệnh.","enabled":true,"requires":"path_kiem_1","minRealm":1,"path":"kiem","objective":{"kind":"kill","count":3,"map":"cave","rare":true},"rewards":{"items":[{"item":"path_item_kiem","qty":1}]}}', updated_at = 0 WHERE id = 'path_kiem';
INSERT OR REPLACE INTO quests (id, chain, seq, enabled, def, updated_at) VALUES ('path_thuat_1', 'path', 3, 1, '{"id":"path_thuat_1","chain":"path","seq":3,"giver":"path_thuat","titleVi":"Lễ vật Yêu Đan","descVi":"Thuật tu cần linh khí cô đọng để thi triển pháp thuật. Mang đến 4 Yêu Đan và 8 Linh Thảo làm lễ vật.","enabled":true,"requires":null,"minRealm":1,"path":"thuat","objective":{"kind":"collect","item":"yeu_dan","qty":4,"also":[{"item":"linh_thao","qty":8}]},"rewards":{"items":[{"item":"dai_hoi_huyet_dan","qty":2}]}}', 0);
UPDATE quests SET seq = 4, def = '{"id":"path_thuat","chain":"path","seq":4,"giver":"path_thuat","titleVi":"Dẫn linh nhập thể","descVi":"Muốn dẫn linh khí vào người phải quen với nơi linh khí nồng đậm. Vào U Minh Động hạ 50 con quái, ta sẽ trao Thuật Tu Lệnh.","enabled":true,"requires":"path_thuat_1","minRealm":1,"path":"thuat","objective":{"kind":"kill","count":50,"map":"cave"},"rewards":{"items":[{"item":"path_item_thuat","qty":1}]}}', updated_at = 0 WHERE id = 'path_thuat';
INSERT OR REPLACE INTO quests (id, chain, seq, enabled, def, updated_at) VALUES ('path_dan_1', 'path', 5, 1, '{"id":"path_dan_1","chain":"path","seq":5,"giver":"path_dan","titleVi":"Dược liệu và đan thuốc","descVi":"Đan tu khởi đầu từ dược liệu và đan cơ bản. Mang đến 30 Linh Thảo và 5 Hồi Huyết Đan.","enabled":true,"requires":null,"minRealm":1,"path":"dan","objective":{"kind":"collect","item":"linh_thao","qty":30,"also":[{"item":"hoi_huyet_dan","qty":5}]},"rewards":{"items":[{"item":"duong_huyet_dan","qty":5}]}}', 0);
UPDATE quests SET seq = 6, def = '{"id":"path_dan","chain":"path","seq":6,"giver":"path_dan","titleVi":"Thử luyện đan","descVi":"Giờ hãy chuẩn bị nguyên liệu cho một mẻ đan thật sự: 10 Dưỡng Huyết Đan, 10 Thú Cốt và 2 Yêu Đan, ta sẽ trao Đan Tu Lệnh.","enabled":true,"requires":"path_dan_1","minRealm":1,"path":"dan","objective":{"kind":"collect","item":"duong_huyet_dan","qty":10,"also":[{"item":"thu_cot","qty":10},{"item":"yeu_dan","qty":2}]},"rewards":{"items":[{"item":"path_item_dan","qty":1}]}}', updated_at = 0 WHERE id = 'path_dan';
UPDATE config_versions SET version = version + 1, updated_at = 0 WHERE name = 'quests';
